import React from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import logo from "../img/logotipo-educaweb.webp";
import { useNavigate } from "react-router-dom";

const Navbar = () => {
  const navigate = useNavigate();

  const handleLogoClick = () => {
    navigate("/"); // Isso redirecionará para a rota raiz que deve ser sua Home
  };

  return (
    <nav className="navbar navbar-light bg-light d-flex justify-content-between px-3">
      <div
        className="d-flex align-items-center"
        style={{ cursor: "pointer" }}
        onClick={handleLogoClick}
      >
        <img
          src={logo}
          alt="EducaWeb"
          width="30"
          height="30"
          className="d-inline-block align-top me-2"
        />
        <span className="navbar-brand mb-0 h1">EducaWeb</span>
      </div>
      <div>
        <div className="d-inline-block ms-3">
          <div
            className="rounded-circle bg-secondary"
            style={{ width: "35px", height: "35px" }}
          ></div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
